function attachmentRefs(src){const refs=[];for(const [kind,list] of KINDS)for(const p of src[list]||[]){refs.push({key:`photo:${kind}:${p.id}`,holder:p,prop:'foto'});if(p.docs&&typeof p.docs==='object')for(const [t,d] of Object.entries(p.docs))if(d&&typeof d==='object'){d.storageKey=d.storageKey||`doc:${kind}:${p.id}:${t}`;refs.push({key:d.storageKey,holder:d,prop:'data',doc:d})}}return refs}
