function renderGallery(){const cls=$('#galleryClass').value,grade=$('#galleryGradeFilter').value;const classes=classList().filter(c=>(!cls||c===cls)&&(!grade||String(c).startsWith(grade)));$('#galleryGrid').innerHTML=classes.map(c=>{const students=data.students.filter(s=>s.kelas===c&&s.status==='Aktif').sort((a,b)=>a.nama.localeCompare(b.nama)),t=teacherFor(c);return `<article class="gallery-card"><div class="gallery-head"><div><h3>Kelas ${esc(c)}</h3><small>${students.length} murid aktif</small></div></div><div class="teacher-chip">${t?avatarHtml(t):'<div class="avatar">♧</div>'}<div><b>${t?esc(t.nama):'Wali kelas belum diatur'}</b><small>${t?esc(t.mapel||'Guru'):'Atur di menu Wali Kelas'}</small></div></div><div class="mini-people">${students.length?students.map(s=>`<div class="mini-person">${avatarHtml(s)}<b title="${esc(s.nama)}">${esc(s.nama.split(' ').slice(0,2).join(' '))}</b><small>${esc(s.status)}</small></div>`).join(''):'<div class="hint">Belum ada murid di kelas ini.</div>'}</div></article>`}).join('')||'<div class="empty-state">Belum ada kelas.</div>'}
function renderCurrent(){refreshClassOptions();if(currentPage==='home'){renderHome();renderGradeRecap()}if(currentPage==='murid')renderStudents();if(currentPage==='pengingat')renderReminders();if(currentPage==='pip')renderPip();if(currentPage==='pemeriksa')renderChecker();if(currentPage==='kepegawaian')renderKepegawaian();if(currentPage==='cetak-murid')renderCetak();if(currentPage==='cetak-guru')renderCetakGuru();if(currentPage==='cetak-rekap')renderCetakRekap();if(currentPage==='walikelas')renderTeachers();if(currentPage==='tenaga')renderStaff();if(currentPage==='alumni'){setSelectOptions($('#alumniYearFilter'),[...new Set(data.students.map(s=>s.tahunAjaran).filter(Boolean).map(String))].sort().reverse(),'Semua tahun ajaran');renderAlumni()}if(currentPage==='foto')renderGallery();if(currentPage==='pengaturan'){ $('#schoolName').value=data.schoolName||'';$('#classList').value=(data.classes||CLASS_DEFAULT).join(', ');renderSchoolLogo();updateStorage();}updateSide()}
function field(name,label,value='',type='text',opts=null,required=false,full=false){let ctrl;if(opts){ctrl=`<select name="${name}" ${required?'required':''}>${opts.map(o=>`<option value="${esc(o)}" ${String(value)===String(o)?'selected':''}>${esc(o||'— Pilih —')}</option>`).join('')}</select>`}else if(type==='textarea'){ctrl=`<textarea name="${name}" ${required?'required':''}>${esc(value)}</textarea>`}else{ctrl=`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'step="any"':''}>`}return `<div class="form-field ${full?'full':''}"><label>${esc(label)}${required?' <span>*</span>':''}</label>${ctrl}</div>`}
function loadImage(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),im=new Image();im.onload=()=>{URL.revokeObjectURL(url);resolve(im)};im.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Gambar tidak dapat dibaca'))};im.src=url})}
function blobToDataUrl(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob)})}
// Perkecil bertahap (tajam), lalu coba format terbaik: turunkan kualitas hanya sampai ukuran target tercapai.
async function shrinkImage(file,{maxW,maxH,maxBytes,formats,keepAlpha}){const img=await loadImage(file);const w=img.naturalWidth,h=img.naturalHeight,scale=Math.min(1,maxW/w,maxH/h),tw=Math.max(1,Math.round(w*scale)),th=Math.max(1,Math.round(h*scale));let src=img,cw=w,ch=h;while(cw/2>tw){cw=Math.round(cw/2);ch=Math.round(ch/2);const c=document.createElement('canvas');c.width=cw;c.height=ch;const x=c.getContext('2d');x.imageSmoothingQuality='high';x.drawImage(src,0,0,cw,ch);src=c}const canvas=document.createElement('canvas');canvas.width=tw;canvas.height=th;const ctx=canvas.getContext('2d',{alpha:!!keepAlpha});if(!keepAlpha){ctx.fillStyle='#fff';ctx.fillRect(0,0,tw,th)}ctx.imageSmoothingQuality='high';ctx.drawImage(src,0,0,tw,th);let smallest=null;for(const [mime,qualities] of formats){for(const q of qualities){const blob=await new Promise(r=>canvas.toBlob(r,mime,q));if(!blob||blob.type!==mime)break;if(!smallest||blob.size<smallest.size)smallest=blob;if(blob.size<=maxBytes)return blob}}if(!smallest)throw new Error('Browser tidak mendukung kompresi gambar');return smallest}
const PHOTO_OPTS={maxW:480,maxH:640,maxBytes:70*1024,formats:[['image/avif',[.72,.6,.5]],['image/webp',[.84,.76,.68,.6]],['image/jpeg',[.86,.78,.7,.62]]]};
const LOGO_OPTS={maxW:256,maxH:256,maxBytes:60*1024,keepAlpha:true,formats:[['image/webp',[.9,.8]],['image/png',[1]]]};
const DOC_OPTS={maxW:1600,maxH:2200,maxBytes:400*1024,formats:[['image/webp',[.85,.78,.7,.62]],['image/jpeg',[.85,.78,.7,.62]]]};
const FORMAT_NAME={'image/avif':'AVIF','image/webp':'WebP','image/jpeg':'JPEG'};
async function convertPhoto(file,done){try{const blob=await shrinkImage(file,PHOTO_OPTS);done(await blobToDataUrl(blob),blob.type,blob.size);toast('Foto dikompres',`${formatBytes(file.size)} → ${formatBytes(blob.size)} (${FORMAT_NAME[blob.type]||blob.type}), tetap tajam untuk pas foto.`)}catch(err){toast('Konversi foto gagal','Browser tidak dapat memproses foto ini. Coba gambar lain (JPG/PNG).','error')}}
async function compressDocumentImage(file){const blob=await shrinkImage(file,DOC_OPTS);return {data:await blobToDataUrl(blob),type:blob.type,size:blob.size}}
function openDataUrl(doc){const m=/^data:([^;,]*)(;base64)?,(.*)$/s.exec(String(doc?.data||''));if(!m){toast('Berkas tidak dapat dibuka','Data berkas rusak.','error');return}const bin=m[2]?atob(m[3]):decodeURIComponent(m[3]);const blob=new Blob([Uint8Array.from(bin,c=>c.charCodeAt(0))],{type:m[1]||doc.type||'application/octet-stream'}),url=URL.createObjectURL(blob);if(!window.open(url,'_blank'))downloadBlob(blob,doc.name||'berkas');setTimeout(()=>URL.revokeObjectURL(url),60000)}
function docUploadField(key,label,docs={}){const d=docs?.[key]||null;return `<div class="doc-upload-field"><label>${esc(label)} <small>(opsional)</small></label><div class="doc-upload-controls"><input type="file" data-doc-input="${esc(key)}" accept=".pdf,.jpg,.jpeg,.png,.webp,.avif,.doc,.docx" hidden><button type="button" class="btn btn-secondary" data-doc-pick="${esc(key)}">${d?'Ganti berkas':'＋ Unggah berkas'}</button>${d?`<button type="button" class="doc-file-link" data-doc-view="${esc(key)}">${esc(d.name||'Lihat berkas')}</button><button type="button" class="text-btn" data-doc-remove="${esc(key)}">Hapus</button>`:'<span class="hint">Gambar (otomatis dikompres) atau PDF maks. 5 MB</span>'}</div></div>`}
