async function backup(){const {unsaved,...rest}=data;const payload={...rest,backupCreated:new Date().toISOString(),backupVersion:3};downloadBlob(new Blob([JSON.stringify(payload)],{type:'application/json'}),`Backup-Data-Sekolah-${new Date().toISOString().slice(0,10)}.json`);data.lastBackup=new Date().toLocaleString('id-ID');data.unsaved=0;persist(false,true);toast('Backup dibuat','File JSON berisi data, foto, dan berkas. Simpan di flashdisk.')}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function restoreBackup(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{const obj=JSON.parse(r.result);if(!Array.isArray(obj.students)||!Array.isArray(obj.teachers))throw Error('format');if(!Array.isArray(obj.staff))obj.staff=[];confirmDialog('Pulihkan backup?',`Backup berisi ${obj.students.length} murid dan ${obj.teachers.length} guru. Data di browser ini akan diganti.`,()=>{data={...freshData(),...obj,unsaved:0};data.students=data.students.filter(x=>x&&typeof x==='object');data.teachers=data.teachers.filter(x=>x&&typeof x==='object');selectedStudentIds.clear();studentPage=teacherPage=alumniPage=staffPage=1;persist(false,true);renderBrand();renderCurrent();toast('Backup dipulihkan',`${data.students.length} murid dan ${data.teachers.length} guru dimuat.`)},'Pulihkan data')}catch(e){toast('Backup tidak valid','Pilih file backup JSON yang dibuat aplikasi ini.','error')}};r.readAsText(file)}

function csvCell(value){const text=String(value??'');return '"'+text.replace(/"/g,'""')+'"'}
function uniqueUsernames(records,kind){const used=new Set();return records.map((record,index)=>{const candidates=kind==='student'?[record.nis,record.nisn,record.id,record.nama]:[record.nip,record.nuptk,record.id,record.nama];let base=String(candidates.find(value=>String(value??'').trim())??`${kind}${index+1}`).trim().replace(/\s+/g,'');if(!base)base=`${kind}${index+1}`;let username=base,n=2;while(used.has(username.toLocaleLowerCase()))username=`${base}_${n++}`;used.add(username.toLocaleLowerCase());return username})}
function safeFileName(name){return String(name||'Murid tanpa nama').normalize('NFKC').replace(/[\\/:*?"<>|\u0000-\u001f]/g,' ').replace(/\s+/g,' ').trim().replace(/[. ]+$/,'')||'Murid tanpa nama'}
function randomPassword(length=10){const alphabet='ABCDEFGHJKMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789';const bytes=new Uint8Array(length);crypto.getRandomValues(bytes);return Array.from(bytes,b=>alphabet[b%alphabet.length]).join('')}
function bytesToBase64(bytes){let binary='';for(let i=0;i<bytes.length;i++)binary+=String.fromCharCode(bytes[i]);return btoa(binary)}
async function encryptStudentPackage(packageData,password){const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12));const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);const key=await crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt']);const plain=new TextEncoder().encode(JSON.stringify(packageData));const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,plain);return {format:'school-student-encrypted',version:1,algorithm:'AES-GCM-256',kdf:'PBKDF2-SHA-256',iterations:250000,salt:bytesToBase64(salt),iv:bytesToBase64(iv),payload:bytesToBase64(new Uint8Array(cipher))}}
async function decryptStudentPackage(obj,password){const fromB64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));const salt=fromB64(obj.salt),iv=fromB64(obj.iv),payload=fromB64(obj.payload);const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);const key=await crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:obj.iterations,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['decrypt']);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,payload);return JSON.parse(new TextDecoder().decode(plain))}
// Mode pemeriksaan lokal: data tetap terenkripsi, tetapi kunci tes ada di JavaScript situs. Bukan untuk kerahasiaan publik.
const STUDENT_TEST_KEY='SMPN6-LOCAL-INSPECTION-KEY-V1-DO-NOT-USE-FOR-PRIVATE-DATA';
async function encryptStudentTestPackage(packageData){const iv=crypto.getRandomValues(new Uint8Array(12));const raw=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(STUDENT_TEST_KEY));const key=await crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},false,['encrypt']);const plain=new TextEncoder().encode(JSON.stringify(packageData));const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,plain);return {format:'school-student-test-encrypted',version:1,algorithm:'AES-GCM-256',keyMode:'site-test-key',iv:bytesToBase64(iv),payload:bytesToBase64(new Uint8Array(cipher))}}
async function decryptStudentTestPackage(obj){const fromB64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));const raw=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(STUDENT_TEST_KEY));const key=await crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},false,['decrypt']);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:fromB64(obj.iv)},key,fromB64(obj.payload));return JSON.parse(new TextDecoder().decode(plain))}

function studentPackageData(st){const normClass=value=>String(value??'').trim().replace(/^kelas\s+/i,'').replace(/\s+/g,'').toLocaleUpperCase('id-ID');const cls=normClass(st?.kelas);const teacher=(data.teachers||[]).find(t=>normClass(t.kelas)===cls);const createdAt=new Date().toISOString();const username=String(st.nis||st.nisn||st.id||st.nama||'murid').trim().replace(/\s+/g,'');return {format:'school-student-data',version:2,createdAt,school:{name:data.schoolName||'Data Sekolah',academicYear:st.tahunAjaran||''},account:{username,role:'Murid',studentId:st.id},student:JSON.parse(JSON.stringify(st,(k,v)=>k==='docs'||k==='storageKey'?undefined:v)),homeroomTeacher:teacher?{nama:teacher.nama,kelas:teacher.kelas,mapel:teacher.mapel||''}:null}}
async function downloadStudentJson(studentId){const st=data.students.find(s=>String(s.id)===String(studentId));if(!st){toast('Murid tidak ditemukan','Muat ulang daftar murid lalu coba lagi.','error');return}try{const obj=await encryptStudentTestPackage(studentPackageData(st));downloadBlob(new Blob([JSON.stringify(obj,null,2)],{type:'application/json;charset=utf-8'}),`${safeFileName(st.nama)}-tes-terenkripsi.json`);toast('JSON tes diunduh',`${st.nama}: terenkripsi dengan kunci tes, bisa dibuka di Portal Murid tanpa password (khusus pemeriksaan).`)}catch(err){console.error(err);toast('Gagal membuat JSON',err?.message||'Terjadi kesalahan.','error')}}
async function downloadSelectedStudentBatch(){const status=$('#studentSelectionStatus'),button=$('#downloadSelectedStudents');const chosen=[...selectedStudentIds].slice(0,50).map(id=>data.students.find(s=>String(s.id)===id)).filter(Boolean);if(!chosen.length){toast('Pilih murid terlebih dahulu','Centang satu atau beberapa murid di daftar.','error');return}if(!window.JSZip){toast('Pustaka ZIP tidak ditemukan','Pastikan folder js/vendor/jszip.min.js ikut terunggah.','error');return}button.disabled=true;const original=button.textContent;button.textContent='Mengenkripsi…';try{await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));const zip=new JSZip(),usedNames=new Map(),passwordRows=[['Nama Murid','Nama File JSON','Password Enkripsi']];for(let i=0;i<chosen.length;i++){const st=chosen[i];let base=safeFileName(st.nama),key=base.toLocaleLowerCase('id-ID'),count=(usedNames.get(key)||0)+1;usedNames.set(key,count);if(count>1)base+=` (${count})`;const password=randomPassword(22),obj=await encryptStudentPackage(studentPackageData(st),password);zip.file(`${base}-terenkripsi.json`,JSON.stringify(obj,null,2));passwordRows.push([st.nama,`${base}-terenkripsi.json`,password]);if(status)status.textContent=`Mengenkripsi paket: ${i+1}/${chosen.length}…`;await new Promise(resolve=>setTimeout(resolve,0))}const csv='\ufeff'+passwordRows.map(row=>row.map(csvCell).join(',')).join('\r\n');const dateTag=new Date().toISOString().slice(0,10);zip.file(`PASSWORD-RAHASIA-Murid-${dateTag}.csv`,csv);if(status)status.textContent=`Mengemas ZIP: 0% (${chosen.length} file)…`;const blob=await zip.generateAsync({type:'blob',compression:'DEFLATE',compressionOptions:{level:3}},meta=>{if(status)status.textContent=`Mengemas ZIP: ${Math.round(meta.percent)}% (${chosen.length} file)…`});downloadBlob(blob,`Paket-JSON-Murid-Terenkripsi-${dateTag}-${chosen.length}-murid.zip`);chosen.forEach(st=>selectedStudentIds.delete(String(st.id)));renderStudents();toast('Unduhan selesai',`${chosen.length} file JSON terenkripsi dan daftar password sudah digabung dalam satu ZIP. Simpan ZIP ini dengan sangat aman; jangan bagikan sebagai satu paket kepada murid.`)}catch(err){console.error(err);if(status)status.textContent='Pembuatan ZIP gagal. Pilihan murid tetap dipertahankan agar bisa dicoba lagi.';toast('Gagal membuat ZIP terenkripsi',err?.message||'Terjadi kesalahan, coba lagi.','error')}finally{button.disabled=false;button.textContent=original;renderStudents()}}
function toggleStudentSelection(studentId,checked){const id=String(studentId);if(checked)selectedStudentIds.add(id);else selectedStudentIds.delete(id);renderStudents()}
function selectCurrentStudentPage(checked){filteredStudents().slice((studentPage-1)*PAGE_SIZE,studentPage*PAGE_SIZE).forEach(s=>checked?selectedStudentIds.add(String(s.id)):selectedStudentIds.delete(String(s.id)));renderStudents()}
function askPassword(){return new Promise(resolve=>{let done=false;const finish=v=>{if(!done){done=true;resolve(v)}};showModal(`<div class="modal-head"><div><h2>Masukkan password</h2><p>Password diberikan sekolah secara terpisah dari file JSON.</p></div><button class="close-modal" data-close aria-label="Tutup">×</button></div><form id="pwForm"><div class="modal-body"><input class="field-input" id="pwInput" type="password" autocomplete="off" required></div><div class="modal-foot"><button type="button" class="btn btn-secondary" data-close>Batal</button><button class="btn btn-primary">Buka Data</button></div></form>`,true);$('#pwInput').focus();$('#pwForm').onsubmit=e=>{e.preventDefault();const v=$('#pwInput').value;closeModal();finish(v)};$$('#modalRoot [data-close]').forEach(b=>b.addEventListener('click',()=>finish(null)));$('#modalRoot .modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))finish(null)})})}
function renderStudentPackage(pkg){const s=pkg.student||{},t=pkg.homeroomTeacher||null,has=v=>v!==undefined&&v!==null&&String(v).trim()!=='';const groups=[['Identitas',[['Nama lengkap',s.nama],['NIS',s.nis],['NISN',s.nisn],['NIK',s.nikAnak],['Tempat, tanggal lahir',[s.tempatLahir,parseISO(s.tanggalLahir)?fmtDate(parseISO(s.tanggalLahir)):s.tanggalLahir].filter(Boolean).join(', ')],['Jenis kelamin',s.jk],['Agama',s.agama],['Alamat',s.alamat]]],['Sekolah',[['Status',s.status],['Kelas',s.kelas],['Tahun ajaran',s.tahunAjaran],['Wali kelas',t?.nama],['Tanggal masuk',s.tanggalMasuk],['Angkatan',s.angkatan],['Kode ijazah',s.kodeIjazah],['Jalur masuk',s.jalurMasuk],['Penerima PIP',s.penerimaPIP]]],['Keluarga',[['Nama ayah',s.ayah],['Pekerjaan ayah',s.kerjaAyah],['Telepon ayah',s.teleponAyah],['Nama ibu',s.ibu],['Pekerjaan ibu',s.kerjaIbu],['Telepon ibu',s.teleponIbu],['Nama wali',s.namaWali],['Pekerjaan wali',s.pekerjaanWali],['Telepon wali',s.teleponWali],['Nomor KK',s.noKK],['Anak ke-',s.anakKe],['Jumlah bersaudara',s.jumlahSaudara]]],['Fisik',[['Tinggi badan',has(s.tinggiBadan)&&s.tinggiBadan+' cm'],['Berat badan',has(s.beratBadan)&&s.beratBadan+' kg']]],['Catatan',[['Catatan',s.catatan]]]];const html=groups.map(([title,rows])=>{const r=rows.filter(x=>x[1]!==false&&has(x[1]));return r.length?`<section class="pkg-group"><h4>${esc(title)}</h4><dl>${r.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(String(v))}</dd></div>`).join('')}</dl></section>`:''}).join('');$('#studentPackageView').innerHTML=`<article class="panel student-package-card"><div class="pkg-head">${avatarHtml(s,true)}<div><h3>${esc(s.nama||'Data Murid')}</h3><p>${esc(pkg.school?.name||'Data Sekolah')}</p></div>${statusPill(s.status)}</div>${html||'<p class="hint">File tidak memiliki rincian yang dapat ditampilkan.</p>'}</article>`}
/* ===== Biodata murid: tampilan rapi + cetak + simpan gambar (logika paket tidak diubah) ===== */
function biodataCardHTML(s,t,schoolName,opts={}){
 const has=v=>v!==undefined&&v!==null&&String(v).trim()!=='';
 const val=v=>has(v)?String(v).trim():'';
 const birth=[val(s.tempatLahir),parseISO(s.tanggalLahir)?fmtDate(parseISO(s.tanggalLahir)):val(s.tanggalLahir)].filter(Boolean).join(', ');
 const photo=safePhotoDataUrl(s.foto);
 const photoHtml=photo?`<img src="${esc(photo)}" alt="Foto ${esc(s.nama)}" style="width:76px;height:100px;object-fit:cover;border-radius:12px;border:1px solid #dbe2ee;background:#fff;display:block">`
  :`<div style="width:76px;height:100px;border-radius:12px;background:#e8edf5;color:#64748b;display:flex;align-items:center;justify-content:center;font-size:28px;font-weight:700">${esc(initials(s.nama)||'?')}</div>`;
 const statusColors={Aktif:['#e8f7ef','#177245'],Mutasi:['#fdf3d7','#8a5a00'],Lulus:['#efeafb','#5b459f']};
 const sc=statusColors[val(s.status)]||['#eef1f6','#475569'];
 const pill=(bg,fg,txt)=>`<span style="display:inline-block;padding:3px 12px;border-radius:999px;font-size:12px;font-weight:700;background:${bg};color:${fg}">${esc(txt)}</span>`;
 const row=(k,v)=>`<div style="display:flex;gap:14px;padding:6px 0;border-bottom:1px dashed #edf0f5"><dt style="flex:0 0 176px;color:#64748b;font-size:13px;line-height:1.45">${esc(k)}</dt><dd style="flex:1;margin:0;color:#111827;font-size:14px;font-weight:500;line-height:1.45;overflow-wrap:anywhere">${esc(String(v))}</dd></div>`;
 const section=(title,rows)=>{
  const r=rows.filter(x=>has(x[1]));
  return r.length?`<section style="padding:2px 24px 6px"><h4 style="margin:14px 0 2px;padding-bottom:6px;font-size:11.5px;letter-spacing:.07em;text-transform:uppercase;color:#7c8db5;border-bottom:1px solid #eef1f6">${esc(title)}</h4><dl style="margin:0">${r.map(x=>row(x[0],x[1])).join('')}</dl></section>`:'';
 };
 const groups=[
  ['Identitas & Data Pribadi',[['NISN',s.nisn],['NIS',s.nis],['NIK',s.nikAnak],['Tempat, tanggal lahir',birth],['Jenis kelamin',s.jk],['Agama',s.agama],['Alamat',s.alamat]]],
  ['Data Sekolah',[['Status',s.status],['Kelas',s.kelas],['Tahun ajaran',s.tahunAjaran],['Wali kelas',t?.nama],['Jalur masuk',s.jalurMasuk],['Tanggal masuk',s.tanggalMasuk],['Angkatan',s.angkatan],['Kode ijazah',s.kodeIjazah],['Penerima PIP',s.penerimaPIP]]],
  ['Orang Tua & Wali',[['Nama ayah',s.ayah],['Pekerjaan ayah',s.kerjaAyah],['Telepon ayah',s.teleponAyah],['Nama ibu',s.ibu],['Pekerjaan ibu',s.kerjaIbu],['Telepon ibu',s.teleponIbu],['Nama wali',s.namaWali],['Pekerjaan wali',s.pekerjaanWali],['Telepon wali',s.teleponWali],['Nomor KK',s.noKK],['Anak ke-',s.anakKe],['Jumlah bersaudara',s.jumlahSaudara]]],
  ['Fisik',[['Tinggi badan',has(s.tinggiBadan)&&s.tinggiBadan+' cm'],['Berat badan',has(s.beratBadan)&&s.beratBadan+' kg']]],
  ['Catatan',[['Catatan',s.catatan]]]
 ];
 const actions=opts.actions?`<div style="display:flex;gap:10px;flex-wrap:wrap;padding:16px 24px 0">
  <button id="bioPrintBtn" type="button" style="display:inline-flex;align-items:center;gap:8px;min-height:38px;padding:0 16px;border:0;border-radius:10px;background:#2563eb;color:#fff;font-weight:650;font-size:13.5px;cursor:pointer">🖨 Cetak Biodata</button>
  <button id="bioImageBtn" type="button" style="display:inline-flex;align-items:center;gap:8px;min-height:38px;padding:0 16px;border:1px solid #dbe2ee;border-radius:10px;background:#fff;color:#334155;font-weight:650;font-size:13.5px;cursor:pointer">⬇ Simpan Gambar</button>
 </div>`:'';
 return `<article class="bio-card" style="font-family:system-ui,-apple-system,'Segoe UI',Roboto,Arial,sans-serif;background:#fff;color:#1f2933;border-radius:18px;border:1px solid #e5e9f0;box-shadow:0 10px 30px rgba(15,23,42,.08);max-width:760px;margin:0 auto;overflow:hidden">
  <header style="display:flex;gap:18px;align-items:center;padding:22px 24px;background:linear-gradient(135deg,#eef3ff,#f8fafd);border-bottom:1px solid #e8edf5">
   ${photoHtml}
   <div style="min-width:0">
    <div style="color:#64748b;font-size:12px;font-weight:600;letter-spacing:.05em;text-transform:uppercase">${esc(schoolName||'Data Sekolah')}</div>
    <h3 style="margin:3px 0 8px;font-size:21px;line-height:1.3;color:#111827;overflow-wrap:anywhere">${esc(s.nama||'Data Murid')}</h3>
    <div style="display:flex;gap:8px;flex-wrap:wrap">${pill(sc[0],sc[1],s.status)}${val(s.kelas)?pill('#e8edf5','#334155',s.kelas):''}</div>
   </div>
  </header>
  ${actions}
  ${groups.map(g=>section(g[0],g[1])).join('')}
  <footer style="display:flex;gap:10px;align-items:flex-start;margin:14px 24px 22px;padding:12px 14px;border-radius:12px;background:#fff7ed;border:1px solid #ffe4c7;color:#9a3412;font-size:12.5px;line-height:1.55">
   <span aria-hidden="true" style="font-size:15px">ℹ️</span>
   <span><b>Perhatian:</b> Jika ada kesalahan pada biodata, segera melapor ke admin/staf tata usaha untuk diperbaiki segera.</span>
  </footer>
 </article>`;
}
function renderStudentPackage(pkg){
 const s=pkg.student||{},t=pkg.homeroomTeacher||null;
 $('#studentPackageView').innerHTML=biodataCardHTML(s,t,pkg.school?.name||'Data Sekolah',{actions:true});
 const pr=$('#bioPrintBtn'),im=$('#bioImageBtn');
 if(pr)pr.onclick=()=>printBiodata(pkg);
 if(im)im.onclick=()=>saveBiodataImage(pkg);
}
function dataUrlToBlob(d){const parts=String(d).split(',');const mime=(/^data:([^;,]+)/.exec(parts[0]||'')||[])[1]||'image/png';const bin=atob(parts[1]||'');const bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);return new Blob([bytes],{type:mime})}
async function saveBiodataImage(pkg){
 const s=pkg.student||{};
 const wrap=document.createElement('div');
 wrap.style.cssText='position:fixed;left:-9999px;top:0;width:760px;z-index:-1;pointer-events:none;';
 wrap.innerHTML=biodataCardHTML(s,pkg.homeroomTeacher||null,pkg.school?.name||'Data Sekolah',{actions:false});
 document.body.append(wrap);
 try{
  const imgs=wrap.querySelectorAll('img');
  await Promise.all([...imgs].map(im=>im.decode?im.decode().catch(()=>{}):Promise.resolve()));
  const node=wrap.firstElementChild;
  const width=node.offsetWidth,height=node.offsetHeight;
  if(!width||!height)throw new Error('layout');
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}"><foreignObject width="100%" height="100%" xmlns="http://www.w3.org/1999/xhtml">${node.outerHTML}</foreignObject></svg>`;
  const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'}));
  const img=new Image();
  await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(new Error('svg'));img.src=url});
  const scale=2,canvas=document.createElement('canvas');
  canvas.width=width*scale;canvas.height=height*scale;
  const ctx=canvas.getContext('2d');ctx.scale(scale,scale);ctx.drawImage(img,0,0,width,height);
  URL.revokeObjectURL(url);
  const name=`Biodata ${safeFileName(s.nama)}`;
  downloadBlob(dataUrlToBlob(canvas.toDataURL('image/png')),`${name}.png`);
  toast('Gambar biodata diunduh',`File PNG ${name}.png siap dipakai (mis. untuk lomba).`);
 }catch(err){
  console.error(err);
  toast('Gagal membuat gambar','Browser tidak mendukung ekspor gambar di perangkat ini. Gunakan tombol Cetak Biodata.','error');
 }finally{wrap.remove()}
}
function printBiodata(pkg){
 const s=pkg.student||{};
 const html=biodataCardHTML(s,pkg.homeroomTeacher||null,pkg.school?.name||'Data Sekolah',{actions:false});
 const doc=`<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Biodata ${esc(s.nama||'Murid')}</title><style>
  @page{size:A4 portrait;margin:12mm}
  html,body{margin:0;padding:0;background:#fff}
  body{font-family:system-ui,-apple-system,'Segoe UI',Roboto,Arial,sans-serif}
  .sheet{padding:0}
 </style></head><body><div class="sheet">${html}</div></body></html>`;
 const fr=document.createElement('iframe');
 fr.id='biodataPrintFrame';
 fr.style.cssText='position:fixed;left:-10000px;top:0;width:1px;height:1px;border:0';
 document.body.append(fr);
 fr.onload=()=>{try{fr.contentWindow.focus();fr.contentWindow.print()}catch(e){console.error(e)}setTimeout(()=>fr.remove(),4000)};
 fr.srcdoc=doc;
}
async function loadStudentPackage(){const file=$('#studentPackageInput').files?.[0],status=$('#studentPackageStatus');if(!file){toast('Pilih file terlebih dahulu','Pilih file JSON paket murid dari sekolah.','error');return}try{const obj=JSON.parse(await file.text());let pkg;if(obj.format==='school-student-test-encrypted'&&obj.version===1&&obj.algorithm==='AES-GCM-256'&&obj.keyMode==='site-test-key'){try{pkg=await decryptStudentTestPackage(obj)}catch(_){throw new Error('File tes terenkripsi rusak atau tidak cocok dengan versi website ini.')}}else if(obj.format==='school-student-encrypted'&&obj.version===1&&obj.algorithm==='AES-GCM-256'){const password=await askPassword();if(password===null)return;if(!password)throw new Error('Password wajib diisi.');try{pkg=await decryptStudentPackage(obj,password)}catch(_){throw new Error('Password salah atau file terenkripsi rusak.')} }else if(obj.format==='school-student-data'&&obj.version===2&&obj.student&&obj.account){if(!confirm('File ini TIDAK terenkripsi. Lanjutkan hanya jika file berasal dari sumber tepercaya dan kamu memang ingin memeriksa data tanpa password.'))return;pkg=obj}else if(obj.format==='school-student-package'&&obj.version===2&&obj.encoding==='base64-utf8-obfuscation'&&obj.payload){const binary=atob(obj.payload),bytes=Uint8Array.from(binary,ch=>ch.charCodeAt(0));pkg=JSON.parse(new TextDecoder().decode(bytes))}else if(obj.format==='school-student-data'&&obj.version===1&&obj.student){throw new Error('File ini memakai format lama. Minta sekolah membuat ulang paket terenkripsi terbaru.')}else throw new Error('Format JSON bukan paket murid yang didukung. Jangan gunakan Backup seluruh sekolah dari Pengaturan & Data.');if(pkg.format!=='school-student-data'||!pkg.student||!pkg.account)throw new Error('Struktur paket murid tidak lengkap.');renderStudentPackage(pkg);status.textContent=`Data ${pkg.student.nama||'murid'} berhasil dibuka pada perangkat ini. File tidak diunggah ke server.`;$('#page-portal-murid .portal-upload-card')?.classList.add('is-collapsed');const toggle=$('#toggleStudentPackageForm');if(toggle){toggle.textContent='Tampilkan panel';toggle.setAttribute('aria-expanded','false')}toast('Data murid berhasil dibuka','Paket terdekripsi dan ditampilkan secara lokal.')}catch(err){$('#studentPackageView').innerHTML='';status.textContent=err.message||'File JSON tidak valid.';toast('Paket JSON tidak dapat dibuka',err.message||'Periksa file yang dipilih.','error')}}
function clearStudentPackage(){ $('#studentPackageInput').value='';$('#studentPackageView').innerHTML='';$('#studentPackageStatus').textContent='Tampilan data dibersihkan.';$('#page-portal-murid .portal-upload-card')?.classList.remove('is-collapsed');const toggle=$('#toggleStudentPackageForm');if(toggle){toggle.textContent='Minimalkan panel';toggle.setAttribute('aria-expanded','true')}}

