const REMIND=[{k:'foto',l:'Belum ada foto',s:'Foto',t:s=>!s.foto},{k:'nisn',l:'NISN kosong',s:'NISN',t:s=>!s.nisn},{k:'nik',l:'NIK anak kosong',s:'NIK',t:s=>!s.nikAnak},{k:'kk',l:'No. KK kosong',s:'No. KK',t:s=>!s.noKK},{k:'lahir',l:'Tanggal lahir kosong',s:'Tgl lahir',t:s=>!s.tanggalLahir},{k:'telp',l:'Telepon orang tua/wali kosong',s:'Telepon',t:s=>!(s.teleponAyah||s.teleponIbu||s.teleponWali)},{k:'berkas',l:'Berkas KK/akta/ijazah SD belum lengkap',s:'Berkas',t:s=>!Object.keys(DOC_LABEL).every(d=>s.docs?.[d])}];
