function pipList(){const q=($('#pipSearch').value||'').toLowerCase().trim(),cls=$('#pipClass').value,g=$('#pipGrade').value;return data.students.filter(x=>x.status==='Aktif'&&x.penerimaPIP==='Ya'&&(!cls||x.kelas===cls)&&(!g||String(x.kelas||'').startsWith(g))&&(!q||[x.nama,x.nis,x.nisn].some(v=>String(v||'').toLowerCase().includes(q)))).sort((a,b)=>String(a.kelas).localeCompare(String(b.kelas),'id',{numeric:true})||String(a.nama).localeCompare(String(b.nama),'id'))}
