 $('#pipStats').innerHTML=[{l:'Penerima PIP (aktif)',v:yes,n:`${act.length?Math.round(yes/act.length*100):0}% dari ${act.length} murid aktif`,c:'#3189ff'},{l:'Bukan penerima',v:act.length-yes-blank,n:'Status PIP “Tidak”',c:'#22c997'},{l:'Status PIP belum diisi',v:blank,n:blank?'Lengkapi di data murid':'Semua sudah diisi',c:'#ffb45e'}].map(x=>`<div class="stat-card" style="--tint:${x.c}"><div class="stat-label">${x.l}</div><div class="stat-value">${x.v}</div><div class="stat-note">${esc(x.n)}</div></div>`).join('');
