 $('#pipRows').innerHTML=page.length?page.map((x,i)=>`<tr><td>${from+i+1}</td><td><div class="student-cell">${avatarHtml(x)}<div><b>${esc(x.nama)}</b><small>NIS ${esc(x.nis||'—')}</small></div></div></td><td><span class="pill pill-blue">${esc(x.kelas||'—')}</span></td><td>${esc(x.nisn||'—')}</td><td>${esc(firstPhone(x)||'—')}</td><td><div class="actions"><button class="action-btn" data-edit-student="${esc(x.id)}" title="Edit" aria-label="Edit ${esc(x.nama)}">${ic('edit')}</button></div></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty-state"><b>Tidak ada penerima PIP</b>Isi kolom “Penerima PIP” pada data murid.</div></td></tr>`;
 $('#pipFooter').textContent=`Menampilkan ${page.length?from+1:0}–${from+page.length} dari ${list.length}`;
 renderPagination('pipPagination',pipPage,max,p=>{pipPage=p;renderPip()});
