/* ---------- Foto massal (kode NISN) ---------- */
const nisnOfFile=name=>{const base=name.replace(/\.[^.]+$/,''),m=base.match(/\d{10}/);return m?m[0]:/^\d{6,9}$/.test(base)?base.padStart(10,'0'):''};
function openBulkPhoto(){
 let plan=[];
 showModal(`<div class="modal-head"><div><h2>Foto Massal (kode NISN)</h2><p>Nama file berisi NISN, contoh: 0123456789.jpg. Foto dikompres otomatis.</p></div><button class="close-modal" data-close aria-label="Tutup">×</button></div><div class="modal-body stack"><input id="bulkPhotoInput" type="file" accept="image/*" multiple><label class="check-row"><input type="checkbox" id="bulkReplace" checked><span>Ganti foto yang sudah ada</span></label><div id="bulkSummary" class="hint">Pilih satu atau banyak foto sekaligus.</div><div class="progress" id="bulkProgress" hidden><i></i></div><div id="bulkReport"></div></div><div class="modal-foot"><button type="button" class="btn btn-secondary" data-close>Tutup</button><button type="button" class="btn btn-primary" id="bulkRun" disabled>Proses foto</button></div>`);
 const byNisn=new Map(data.students.filter(x=>x.nisn).map(x=>[String(x.nisn).trim().padStart(10,'0'),x]));
 $('#bulkPhotoInput').onchange=e=>{const seen=new Map();[...e.target.files].forEach(f=>seen.set(nisnOfFile(f.name)||'_'+f.name,f));plan=[...seen.entries()].map(([k,f])=>({f,nisn:k,st:byNisn.get(k)}));const ok=plan.filter(p=>p.st),bad=plan.filter(p=>!p.st),dup=e.target.files.length-plan.length;
  $('#bulkSummary').innerHTML=`<b>${ok.length}</b> foto cocok dengan murid, <b>${bad.length}</b> tidak cocok${dup>0?`, ${dup} file ganda untuk NISN yang sama (dipakai yang terakhir)`:''}.`;
  $('#bulkReport').innerHTML=bad.length?`<div class="import-validation-errors"><b>Tidak cocok:</b> ${bad.slice(0,25).map(p=>esc(p.f.name)).join(', ')}${bad.length>25?` … +${bad.length-25} lagi`:''}<br>Periksa NISN pada nama file atau data murid.</div>`:'';
  $('#bulkRun').disabled=!ok.length};
 $('#bulkRun').onclick=async()=>{const rep=$('#bulkReplace').checked,todo=plan.filter(p=>p.st&&(rep||!p.st.foto)),skipped=plan.filter(p=>p.st).length-todo.length,fail=[];let done=0;$('#bulkRun').disabled=true;$('#bulkPhotoInput').disabled=true;const bar=$('#bulkProgress');bar.hidden=false;
  for(const p of todo){try{p.st.foto=await blobToDataUrl(await shrinkImage(p.f,PHOTO_OPTS));done++}catch(_){fail.push(p.f.name)}$('#bulkProgress i').style.width=Math.round((done+fail.length)/todo.length*100)+'%';$('#bulkSummary').textContent=`Memproses ${done+fail.length} dari ${todo.length}…`;if((done+fail.length)%40===0)persist(false,true);await new Promise(r=>setTimeout(r))}
  persist(false);renderCurrent();$('#bulkSummary').innerHTML=`<b>Selesai.</b> ${done} foto disimpan${skipped?`, ${skipped} dilewati (sudah punya foto)`:''}${fail.length?`, ${fail.length} gagal`:''}.`;$('#bulkReport').innerHTML=fail.length?`<div class="import-validation-errors"><b>Gagal diproses:</b> ${fail.map(esc).join(', ')}</div>`:'';toast('Foto massal selesai',`${done} foto dikompres dan disimpan.`)};
}
$('#bulkPhoto').onclick=openBulkPhoto;

