const LIST_SFX=['Source','Class','Title','Sub','Date','Place','Note','Blank1','Blank2','Blank3','SignPlace','SignRole','SignName','SignNip','Orient'],LIST_CHK=['ColNis','ColNisn','ColGol','ColKelas','ColJk','Kop','Sign'];
