function loadListPrefs(P){const c=LIST_CFG[P],p=data[c.pref]||{};COLCFG[P]=p[P+'ColCfg']&&typeof p[P+'ColCfg']==='object'?p[P+'ColCfg']:{};{const cs=lget(P,'ColSet');if(cs)cs.dataset.sig=''}if(Object.keys(p).length){LIST_SFX.forEach(s=>{const e=lget(P,s);if(e&&p[P+s]!==undefined)e.value=p[P+s]});LIST_CHK.forEach(s=>{const e=lget(P,s);if(e&&p[P+s]!==undefined)e.checked=p[P+s]})}else{applyPreset(P,'hadir',true);lget(P,'Source').value=c.def}const src=lget(P,'Source');if(!c.sources.includes(src.value))src.value=c.def}
