 const cs=classList();$('#cetakClass').innerHTML=`<option value="all">Semua murid aktif</option><option value="g7">Semua kelas 7</option><option value="g8">Semua kelas 8</option><option value="g9">Semua kelas 9</option>`+cs.map(k=>`<option value="${esc(k)}">Kelas ${esc(k)}</option>`).join('');
 {const pc=$('#cetakPickClass'),keep=pc.value;pc.innerHTML=$('#cetakClass').innerHTML;if(keep)pc.value=keep}
