$('#cgPickAll').onclick=()=>{const q=$('#cgPickSearch').value.trim().toLowerCase();cgPool().filter(r=>!q||`${r.nama} ${r.kelas} ${r.gol}`.toLowerCase().includes(q)).forEach(r=>cgPickSel.add(r.key));renderCgPick();updateCetakGuru()};
