const PAPER_MM={f4:{portrait:215,landscape:330},a4:{portrait:210,landscape:297}};
function printDoc(html,opt,title){if(typeof opt==='boolean')opt={paper:'f4',landscape:opt};const paper=PAPER_MM[opt.paper]||PAPER_MM.f4,land=!!opt.landscape,w=land?paper.landscape:paper.portrait,h=land?paper.portrait:paper.landscape;$('#printReport').innerHTML=`<div class="doc">${html}</div>`;const st=document.createElement('style');st.id='dynPage';st.textContent=`@page{size:${w}mm ${h}mm;margin:15mm}`;document.head.append(st);const old=document.title;document.title=title;window.addEventListener('afterprint',()=>{document.title=old;st.remove()},{once:true});const imgs=[...$('#printReport').querySelectorAll('img')];Promise.all(imgs.map(i=>i.decode?i.decode().catch(()=>{}):0)).then(()=>window.print())}
